\section{Definitions}
\label{sec:defs}

\paragraph{Distributions.}
We denote the $n$-dimensional Hamming cube by $\pmo^n$.
Given a
probability distribution $\psi$ on $\pmo^n$, it is convenient to
identify it with the probability measure $\psi: \pmo^n \rgta \R^{\geq 0}$ which satisfies
\[
\E_{\x \sim \pmo^n} [\psi(\x)] = 1.
\]
We write $\x \sim \psi$ to denote $\x$ is a random variable with the
distribution
\[
\Pr_{\x \sim \psi}[\x = x] = \frac{\psi(x)}{2^n}
\]
Henceforth, we will interchangeably refer to $\psi$ as a distribution
and a measure. We will use $\mu$ to denote the uniform distribution over
$\pmo^n$, where $\mu(x) =1$ for all $x \in \pmo^n$.
Given functions $f, g: \pmo^n \rgta \R$, we define their inner product by
$\ip{f,g} \defeq \E_{\x \sim \mu}[f(\x)g(\x)]$. For two probability measures
$\psi, \theta$, we have
\[ \ip{\psi, \theta} = \sum_{x \in \pmo^n} \frac{\psi(x)\theta(x)}{2^n} =
  \E_{\x \sim \psi}[\theta(\x)] = \E_{\x \sim \theta}[\psi(\x)].\]

Let $A \subseteq \pmo^n$ and let $\alpha = |A|/2^n$ denote its
fractional density. We use $\mu_A$ to denote the uniform distribution
over $A$. The corresponding measure is defined as
\begin{align}
  \label{eq:mu_a}
  \mu_A(\x) =
  \begin{cases}
    \frac{1}{\alpha} & \text{if} \ x \in A\\
    0 & \text{otherwise}
  \end{cases}
\end{align}

For a distribution $\psi$, we define \[ \inorm{\psi} = \max_{x \in \pmo^n} \psi(x)\]

\paragraph{Subcubes.}

A subcube is a subset of $\pmo^n$ obtained by fixing some subset of
bits to a particular value. Formally, a subcube $C \subseteq \pmo^n$
is specified by a pair $(K, y)$ where $K \subseteq [n]$ and
$y \in \pmo^{K}$. We have
\[ C = \{x \in \pmo^n \ \st \  x_i = y_i \ \forall \ i \in K \}. \]
We refer to coordinates in $K$ as the fixed coordinates of $C$, and
to the rest as the free coordinates of $C$. For $C = (K,y)$ we define
the codimension of $C$ to be $|K|$ and denote it $\codim(C)$.
By Equation \eqref{eq:mu_a}, $\mu_C$ the uniform measure over $C$ is given by
  \begin{align*}
    \mu_C(x)    & = \begin{cases}
      2^{\codim(C)} & \ \text{if} \ x \in C\\
      0 & \ \text{if} \ x \not\in C\\
    \end{cases}
  \end{align*}

For subcubes $C = (K,y), D = (L,z)$, we have $D \subset C$ iff $K
\subset L$ and $z_i = y_i$ for all $i \in K$. We refer to $D$ as a
child of $C$ and $C$ as a parent of $D$.

\begin{definition}(Restriction)
  \label{def:restr}
For a distribution $\psi$ on $\pmo^n$ and a subcube $C \subseteq
\pmo^n$ such that $\psi$ assigns non-zero probability to $C$
we define $\restr{\psi}{C}: C \rightarrow  \R^{\geq 0}$, the
restriction of $\psi$ to $C$, as
\begin{align*}
  \restr{\psi}{C} (x)  =  \frac{\psi(x)}{\ip{\psi, \mu_C}}.
\end{align*}
\end{definition}

\subsection{Skewed subcubes}

\begin{definition}[Skew]
  \label{def:skew}
	We define the \textbf{skew} of a subcube $C$ with respect to
        measure $\psi$ as
	\[ \skew_\psi(C) = \ip{\psi, \mu_C} - 1\]
\end{definition}

\subsection{Minimal skewed subcubes}

\begin{definition}
\label{def:min_skew}
  Let $\gamma \in(0,2^k -1]$ and $\eps \in (0,1]$. A subcube $C
    \subseteq \pmo^n$ is a $(\gamma, \eps)$-minimally
  skewed subcube if $\skew(C) \geq \gamma$ and for all its parent
  subcubes $D \supsetneq C$, we have
  \begin{align}
    \label{eq:min_skew}
    \skew_\psi(D) \leq (1 - \eps)\gamma.
  \end{align}
Let $\gamma \in (0,1]$ and $\eps \in (0,1]$. A subcube $C \subseteq
  \pmo^n$ is a $(-\gamma, \eps)$-minimally skewed subcube if
  $\skew(C) \leq -\gamma$ and for all its parent  subcubes $D \supsetneq C$, we have
  \begin{align}
    \label{eq:min_skew_neg}
    \skew_\psi(D) \geq -(1 - \eps)\gamma.
  \end{align}
\end{definition}

\section{Fourier Analysis}
\label{sec:fourier}

Given $S \subseteq [n]$, let $\chi_S: \pmo^n \rgta \pmo$ be given by
$\chi_S(x) = \prod_{i \in S}x_i$. These functions form a basis so we
can write $\psi = \sum_S \widehat \psi(S) \chi_S$, where the  Fourier
coefficients of $\psi$ are given by
\begin{align*}
  \hatpsi(S) = \E_{\x \sim \mu}[\psi(\x)\chi_S(\x)] = \sum_{x \in \pmo^n}\frac{\psi(x)\chi_S(x)}{2^n}
  = \sum_{x \in \pmo^n}\Pr_{\x \sim \psi}[\x = x]\chi_S(x) = \E_{\x \sim \psi}[\chi_S(\x)]
\end{align*}

We also need a bound for the Fourier mass at level $k$ where we do not
count coordinates from some set $J \subseteq [n]$ in the degree of a
coefficient.
\[ W^{\leq k}(\psi, J) = \sum_{T \subseteq J} \sum_{\substack{S
      \subseteq [n]\setminus J \\ |S| \leq k}}\hatpsi(S \cup T)^2.\]

\begin{restatable}{corollary}{corlevel}
  \label{cor:level_k}
  For $J \subseteq [n]$ and a distribution $\psi$ over $\pmo^n$,
  \[ W^{\leq k}(\psi, J)   \leq 2^{|J|}e^2 (\ln(e \inorm{\psi}))^k. \]
\end{restatable}

\begin{restatable}{lemma}{restriction}
  \label{lem:restrict}
  Let $C = (J, z)$. Then
  \[ \restr{\psi}{C}(x) = \sum_{S \subseteq [n]\setminus J} \chi_S(x) \frac{\sum_{T
    \subseteq J} \hatpsi(S \cup T)\chi_T(z)}{\ip{\psi, \mu_C}}. \]
\end{restatable}

\section{A Combinatorial Bound for minimal skewed subcubes}
\label{sec:comb}

\subsection{Positive skew}
\label{subsec:pos}

	\begin{algorithm}[ht]
		\caption{$\fsr(R_{t}, y_{t})$}
		\label{alg:find_skew_recursive}
		\begin{algorithmic}[1]
		  \State Let $D_{t} = (R_{t}, y_{t})$.  Let $\psi_t =
                  \restr{\psi}{D_{t}}$. Let $k_{t} = k - |R_t|$.
		\If{$\skew_\psi(D_{t})  > \gamma(1 - \eps)$}\\
			\Return $D_t$ \label{line:return}
		\EndIf
		\If{$\ip{\psi, \mu_{D_t}} < (1 + \gamma)\cdot 2^{-k_t}$}\label{line:test}\\
			\Return FAIL \label{line:fail}
			\EndIf
                \State Pick $S_t$ such that $|S_t| \leq k_{t}$ and \label{line:guess_s}
                  \begin{align}
                    \label{eq:guess_s}
                    |\widehat{\psi_t}(S_t)| \geq
                        \frac{\eps\sqrt{\gamma}}{ k_{t} \cdot
                          \binom{k_{t}}{|S_t|}}.
                  \end{align}
                  \State Pick $z_t \in \pmo^{S_t}$. \label{line:guess_z}
                  \State \Return $\fsr(R_t \cup S_t, y_t \circ z_t)$.
		\end{algorithmic}
	\end{algorithm}

We need some notation for the analysis. Let the sequence of subcubes
produced by the algorithm be $D_0 \supsetneq D_1 \cdots \supsetneq D_\ell$.
Let $s_t = |S_t|$.

        \begin{lemma}
          \label{lem:complete}
          For every $(\gamma,\eps)$-minimal skewed subcube $C$ with $\codim(C) \leq  k$
          there are sequences of choices of $S_t$ and  $z_t$ (in
          \cref{line:guess_s,line:guess_z}) so that $C$ is returned by
          $\fsr$.
        \end{lemma}

          \begin{lemma}\label{lem:guess_s}
            The number of choices for $S_t$ satisfying Equation
            \eqref{eq:guess_s} is bounded by
            \[ \frac{e^2}{\eps^2\gamma} (\ln(2^{k_t} e \inorm{\psi}))^{s_t}k_t^{4s_t + 2}.\]
          \end{lemma}

\section{Algorithms for Finding Skewed Subcubes}
\label{sec:algo}

	\begin{theorem}[\cite{KarppaKK18}]
		\label{thm:subquad_corr}
		Given two sets of vectors $V_1, V_2 \subseteq \pmo^n$
                for which there are at most $q$ pairs $(v_1, v_2) \in
                V_1 \times V_2$ with correlation larger than $\tau$,
                and a parameter $\rho \geq \tau^{1/\lambda}$ (for $\lambda \in [0,1]$), there is an
                algorithm $\textsc{FindCorr}(V_1, V_2, \rho, \tau)$
                that with high probability outputs all pairs $(v_1,
                v_2) \in V_1 \times V_2$ with correlation at least
                $\rho$. Furthermore,  algorithm runs in time
                \[\tilde O\left(n^{\frac{2 \omega}{3 - \lambda}} +
                qdn^{\frac{2(1 - \lambda)}{3 - \lambda}}\right).\]
	\end{theorem}

	\begin{algorithm}[ht]
		\caption{$\ffc(\psi, k, \rho, \lambda)$}
		\label{alg:find_fourier}
		\begin{algorithmic}[1]
			\State $\mathcal{S} \leftarrow \emptyset$
			\State $\tau \leftarrow (\rho/2)^{1/\lambda}$
			\State Draw a set of $d= O(k \log n /\tau^2)$ samples $x_1, \ldots x_d$  from $\psi$.
			\For{$T = O(k^{3/2} \log n)$ rounds}
			\State Randomly partition $[n]$ into two subsets $N_1$ and $N_2$.
			\State For every subset $S\subseteq N_1$ of size $\leq \lceil k/2\rceil$, form a vector $y_S \in [-1,1]^d$ for which the $i$th bit is set to $\chi_S(x_i)$. Call this set of vectors $V_1$.
			\State Do the same for $N_2$ for sets of size $\leq \lfloor k/2 \rfloor$, and call the set of vectors $V_2$.
			\State Run $\textsc{FindCorr}(V_1, V_2, \rho/2, \tau)$ from \cite{KarppaKK18} to find all pairs $y_Q$ and $y_R$ such that $Q \subseteq N_1$, $R \subseteq N_2$, and $y_Q$ and $y_R$ are $\rho/2$ correlated. For each of these, add $Q \cup R$ to $\mathcal{S}$. \label{line:corr_pairs}
			\EndFor
			\State \Return $\mathcal{S}$.
		\end{algorithmic}
	\end{algorithm}

\begin{lemma}
\label{lem:ffc}
	The algorithm $\ffc(\psi, k, \rho, \lambda)$ returns all
        Fourier coefficients of $\psi$ of degree at most $k$ of
        absolute value at least $\rho$ in time 
        \[\tilde O \left( n^{k\omega/(3 - \lambda)} \right) +
        \tilde O(n^{k/3}) 2^{O(k)} (\ln(e \inorm{\psi}))^k\rho^{-4/\lambda}.\]
\end{lemma}

We preprocess $L$ by creating a graph $G_L$. Vertices of this graph are indexed by elements of the power set $2^{[n]}$. For each coefficient $S \in L$, and each subset $T \subset S$, add the directed edge $T \rightarrow S$. Furthermore, each $T$ stores $k$ lists, where the $i^{th}$ list contains all sets $S$ in the out-neighborhood of $T$ such that $|S \backslash T| = i$. Since $2^k|L|$ is a bound on both the total number of edges and the total number of vertices in the graph, creating the graph takes $O(2^k |L|)$ time. Creating the partitions of the out-neighborhoods also takes $O(2^k |L|)$ times since each edge in the graph need only be processed once.

\begin{algorithm}[ht]
	\caption{$\pc(L)$}
	\label{alg:preprocess}
	\begin{algorithmic}[1]
		\State $V, E \leftarrow \emptyset$
		\For{$S \in L$}
		\For{$T \subseteq S$}
		\State $V \leftarrow V \cup \{S, T\}$
		\State $E \leftarrow E \cup \{(T \rightarrow S)\}$
		\EndFor
		\EndFor
		\For{edge $(T \rightarrow S) \in E$}
		\State Let $i = |S \backslash T|$, and add $S$ to the $i^{th}$ list stored at $T$.
		\EndFor
		\State \Return $G_L = (V, E)$
	\end{algorithmic}
\end{algorithm}

Next, given $G_L$ the preprocessed form of $L$, a target subcube $C = (J,z)$ and a threshold $\tau$, we show how to output all Fourier coefficients $\widehat{\restr{\psi}{C}}(S)$ such that $\widehat{\restr{\psi}{C}}(S) \geq \tau$.

\begin{algorithm}[ht]
\caption{$\dsc(G_L, C, \tau)$}
\label{alg:deduce_subcube_coeffs}
\begin{algorithmic}[1]
	\State Let $J$ be the coordinates fixed by $C$.
	\State $L' \leftarrow \emptyset$
	\For{$T \subseteq J$}
	\For{$S$ out-neighbor of $T$ in $G_L$ with $|S \backslash T| \leq k - |J|$}
	\State Check by sampling if $\left|\widehat{\restr{\psi}{C}}(S\backslash J)\right| \geq 3\tau/4$ to accuracy $\tau/4$. If so, add $S\backslash J$ to $L'$.
	\EndFor
	\EndFor
	\State \Return $L'$.
\end{algorithmic}
\end{algorithm}


